#include <stdio.h>

int main(void) {
    FILE *file = fopen("log.txt", "w");
    if (file == NULL) return 1;
    int ok = fprintf(file, "record=%d\n", 12) >= 0;
    if (fflush(file) == EOF) ok = 0;
    if (fclose(file) == EOF) ok = 0;
    return ok ? 0 : 1;
}

#include <stdio.h>

int main(void) {
    FILE *file = fopen("report.txt", "w");
    if (file == NULL) return 1;
    int failed = fputs("Report\n", file) == EOF;
    if (fclose(file) == EOF) failed = 1;
    return failed ? 1 : 0;
}
